const data = $input.item.json;

const quantity = data['Quantity'];
const unitPrice = data['Unit Price'];
const discount = data['Discount%'];
const tax = data['Tax%'];

const subtotal = quantity * unitPrice;
const discountAmount = subtotal * (discount / 100);
const afterDiscount = subtotal - discountAmount;
const taxAmount = afterDiscount * (tax / 100);
const total = afterDiscount + taxAmount;
const invoiceNumber = 'INV-' + Date.now();

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8">
<style>
body{font-family:Arial,sans-serif;padding:40px;color:#333}
h1{color:#2c3e50}
table{width:100%;border-collapse:collapse;margin:20px 0}
th{background:#2c3e50;color:white;padding:10px;text-align:left}
td{padding:10px;border-bottom:1px solid #eee}
.totals table{width:300px;margin-left:auto}
.total-row{font-weight:bold;font-size:18px;color:#2c3e50}
</style></head>
<body>
<h1>INVOICE</h1>
<p><strong>Invoice #:</strong> ${invoiceNumber}</p>
<p><strong>Date:</strong> ${new Date().toLocaleDateString()}</p>
<p><strong>Due Date:</strong> ${data['Due Date']}</p>
<p><strong>Bill To:</strong> ${data['Customer Name']} — ${data['Customer Email']}</p>
<table>
  <tr><th>Description</th><th>Qty</th><th>Unit Price</th><th>Amount</th></tr>
  <tr><td>${data['Item Description']}</td><td>${quantity}</td><td>₱${unitPrice.toLocaleString()}</td><td>₱${subtotal.toLocaleString()}</td></tr>
</table>
<div style="text-align:right;margin-top:20px">
  <table style="width:300px;margin-left:auto;border-collapse:collapse">
    <tr><td style="padding:8px">Subtotal</td><td style="padding:8px">₱${subtotal.toLocaleString()}</td></tr>
    <tr><td style="padding:8px">Discount (${discount}%)</td><td style="padding:8px">-₱${discountAmount.toLocaleString()}</td></tr>
    <tr><td style="padding:8px">Tax (${tax}%)</td><td style="padding:8px">₱${taxAmount.toFixed(2)}</td></tr>
    <tr style="font-weight:bold;font-size:18px;color:#2c3e50"><td style="padding:8px">Total</td><td style="padding:8px">₱${total.toFixed(2)}</td></tr>
  </table>
</div>
<p style="margin-top:40px;text-align:center;color:#888">Thank you for your business!</p>
</body></html>`;

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(html, 'utf8'),
  'index.html',
  'text/html'
);

return {
  json: { invoiceNumber, customerName: data['Customer Name'], customerEmail: data['Customer Email'], total: total.toFixed(2) },
  binary: { data: binaryData }
};
